breaking_changes.Adaptation_method:
Use named exports instead of default export. For example, change:
const replaceInFile = require('replace-in-file');
// or
import replaceInFile from 'replace-in-file';

To:
const { replaceInFile, replaceInFileSync } = require('replace-in-file');
// or
import { replaceInFile, replaceInFileSync } from 'replace-in-file';

Use the named export `replaceInFileSync` instead. For example, change:
const replace = require('replace-in-file');
const results = replace.sync(options);

To:
const { replaceInFileSync } = require('replace-in-file');
const results = replaceInFileSync(options);

Use promises or async/await instead of callbacks. For example, change:
replaceInFile(options, (error, results) => {
  if (error) {
    console.error('Error:', error);
  } else {
    console.log('Results:', results);
  }
});

To:
try {
  const results = await replaceInFile(options);
  console.log('Results:', results);
} catch (error) {
  console.error('Error:', error);
}

Or with promises:
replaceInFile(options)
  .then(results => console.log('Results:', results))
  .catch(error => console.error('Error:', error));

For async API, use `fs` parameter that provides `readFile` and `writeFile` methods. For sync API, use `fsSync` parameter that provides `readFileSync` and `writeFileSync` methods. For example:

// For async API
const options = {
  files: 'path/to/file',
  from: 'foo',
  to: 'bar',
  fs: customFsImplementation // must have readFile and writeFile methods
};

// For sync API
const optionsSync = {
  files: 'path/to/file',
  from: 'foo',
  to: 'bar',
  fsSync: customFsSyncImplementation // must have readFileSync and writeFileSync methods
};
